{
  "name": "@bruceyao241/opencode-gpt-usage",
  "version": "0.2.6",
  "description": "ChatGPT (Codex) weekly quota card for the opencode TUI right sidebar — WEEKLY ▓▓▓▓▓▓▓░░░ 70% left · resets 14:30.",
  "type": "module",
  "license": "MIT",
  "author": "zhufengyao <527936342@qq.com>",
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "tui",
    "plugin",
    "chatgpt",
    "codex",
    "gpt",
    "quota",
    "usage",
    "sidebar",
    "wham"
  ],
  "homepage": "https://github.com/BruceYao241/opencode-gpt-usage",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/BruceYao241/opencode-gpt-usage.git"
  },
  "bugs": {
    "url": "https://github.com/BruceYao241/opencode-gpt-usage/issues"
  },
  "engines": {
    "opencode": ">=1.18"
  },
  "exports": {
    "./tui": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun run build.ts && tsc -p tsconfig.json",
    "typecheck": "tsc --noEmit -p tsconfig.json && tsc --noEmit -p tsconfig.test.json",
    "test": "bun test",
    "check": "bun run typecheck && bun test",
    "prepublishOnly": "bun run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18",
    "@opentui/solid": "*",
    "solid-js": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.0",
    "@opentui/solid": "^0.4.3",
    "@types/node": "^26.1.1",
    "bun-types": "latest",
    "solid-js": "*",
    "typescript": "^5"
  }
}
